import id from 'hyphen/patterns/id.js';
import is from 'hyphen/patterns/is.js';
import it from 'hyphen/patterns/it.js';
import ka from 'hyphen/patterns/ka.js';
import kmr from 'hyphen/patterns/kmr.js';
import kn from 'hyphen/patterns/kn.js';
import la from 'hyphen/patterns/la.js';
import lt from 'hyphen/patterns/lt.js';
