import or from 'hyphen/patterns/or.js';
import pa from 'hyphen/patterns/pa.js';
import pl from 'hyphen/patterns/pl.js';
import pms from 'hyphen/patterns/pms.js';
import pt from 'hyphen/patterns/pt.js';
import rm from 'hyphen/patterns/rm.js';
import ro from 'hyphen/patterns/ro.js';
import ru from 'hyphen/patterns/ru.js';
