import te from 'hyphen/patterns/te.js';
import th from 'hyphen/patterns/th.js';
import tk from 'hyphen/patterns/tk.js';
import tr from 'hyphen/patterns/tr.js';
import uk from 'hyphen/patterns/uk.js';
import zh from 'hyphen/patterns/zh-latn-pinyin.js';

const langPatterns = {
  af, as, be, bg, bn, ca, cop, cs, cu, cy, da, de, el, en, 'en-gb': enGb, 'en-us': enUs, eo, es, et, eu, fi, fr, fur, ga, gl, grc, gu, hi, hr, hsb, hu, hy, ia, id, is, it, ka, kmr, kn, la, lt, lv, ml, mn, mr, nb, nl, nn, no, or, pa, pl, pms, pt, rm, ro, ru, sa, sh, sk, sl, sr, sv, ta, te, th, tk, tr, uk, zh,
};

const defaultHyphenate = hyphenLib(patterns);

export const hyphenateWord = (word, lang = 'en-us') => {
  const p = langPatterns[lang] || patterns;
  const h = hyphenLib(p);
  return h(word).split('\u00AD');
};

export const hyphenate = (word, lang) => hyphenateWord(word, lang).join('\u00AD');
export const syllables = (word, lang = 'en-us') => {
  const p = langPatterns[lang] || patterns;
  const h = hyphenLib(p);
  const res = h(word);
  return res.split('\u00AD').filter(Boolean);
};

export default { hyphenate, hyphenateWord, syllables };
